// Interface languages: Vietnamese (default), English and Chinese.
inline std::string supportedLanguage(const std::string &value) { return value == "en" || value == "zh" ? value : "vi"; }
inline std::string text(std::string_view key, const std::string &language = "vi") {
    for (const auto &entry : copy) if (entry.key == key) return language == "zh" ? (entry.zh ? entry.zh : entry.en) : language == "en" ? entry.en : entry.vi;
    return std::string(key);
}
